import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const group = process.argv[2];
function check(input, expected) {
  assert.equal(slugify(input), expected, JSON.stringify(input));
}
if (group === 'accents') {
  check('Crème Brûlée', 'creme-brulee');
  check('Łódź', 'lodz');
  check('  CAFÉ, déjà vu!  ', 'cafe-deja-vu');
  // Exhaustively cover canonical Latin accent decompositions with an ASCII base.
  let count = 0;
  for (let cp = 0; cp <= 0x2fff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || !/^\p{Script=Latin}$/u.test(letter)) continue;
    const decomposed = letter.normalize('NFD');
    if (!/^[A-Za-z]\p{M}+$/u.test(decomposed)) continue;
    const expected = decomposed[0].toLowerCase();
    check(letter, expected);
    check(decomposed, expected);
    check(`X${letter}Y`, `x${expected}y`);
    check(`X${decomposed}Y`, `x${expected}y`);
    count++;
  }
  assert.ok(count > 400);
  check('Cafe\u0301 noir', 'cafe-noir');
  check('A\u030a\u0301ngstro\u0308m', 'angstrom');
  check('a\u0301\u0323\u0304b', 'ab');
} else if (group === 'specials') {
  const pairs = [
    ['Ææ', 'aeae'], ['Œœ', 'oeoe'], ['Øø', 'oo'],
    ['Łł', 'll'], ['Đđ', 'dd'], ['Ðð', 'dd'], ['Þþ', 'thth'],
    ['Ħħ', 'hh'], ['Ŧŧ', 'tt'], ['Ŋŋ', 'nn'], ['ı', 'i'],
    ['ſ', 's'], ['ẞß', 'ssss'], ['ƒ', 'f'],
    ['Ǣǣ', 'aeae'], ['Ǽǽ', 'aeae'], ['Ǿǿ', 'oo'],
    ['ﬀ ﬁ ﬂ ﬃ ﬄ ﬅ ﬆ', 'ff-fi-fl-ffi-ffl-st-st'],
  ];
  for (const [input, expected] of pairs) {
    check(input, expected);
    check(input.normalize('NFD'), expected);
    check(`A${input}Z`, `a${expected}z`);
  }
  check('Straße smørrebrød cœur encyclopædia', 'strasse-smorrebrod-coeur-encyclopaedia');
  check('Dvořák Łódź Þingvellir Đà Nẵng', 'dvorak-lodz-thingvellir-da-nang');
  check('ø\u0301 æ\u0304 ß\u0301 ł\u0307', 'o-ae-ss-l');
} else if (group === 'preserve') {
  const legacy = title => title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
  const samples = [
    '', '  --  ', 'Hello, World!', '  --Release 2.0--  ',
    'a_b/c.d\\e', 'A\tB\nC', 'foo---bar', '123 ٤٥٦ １２３',
    'Привет мир', 'Й Ё й ё', 'Ελληνικά ΆΈΉΊΌΎΏ ΐ ΰ',
    '日本語 東京 カタカナ ひらがな', '中文 汉字', '한국어 한글',
    'العربية', 'עברית', 'हिन्दी', 'বাংলা', 'ไทย',
    'ქართული', 'Հայերեն', 'ᎠᎡᎢ', '𐐀𐐁', '🙂 Hello 🚀 World!',
  ];
  for (const input of samples) check(input, legacy(input));
  // Non-Latin letters must not be globally decomposed, transliterated or dropped.
  for (let cp = 0; cp <= 0x2fff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || /^\p{Script=Latin}$/u.test(letter)) continue;
    check(`A${letter}Z`, legacy(`A${letter}Z`));
  }
} else {
  throw new Error('Unknown acceptance group: ' + group);
}
